#!/usr/bin/env python3
"""Add three opt-in switches for func_002900B8: two cse rules and one reload_cse rule.

- -frac2-cse2-keep-multi-set-reg (cse.c make_regs_eqv): in the cse pass after loop, a pseudo set
  once does not displace a pseudo with several sets as a quantity's canonical register.
- -frac2-cse-arg-hard-reg (cse.c cse_insn): a hard-register load whose source is a constant or a
  hard register is not rewritten to read a pseudo with several sets; for a constant, another hard
  register of the same quantity is used instead.
- -frac2-reload-cse-branch-to-next (reload1.c reload_cse_regs_1): register values are kept at a
  label whose only users are the conditional branches directly in front of it.

In func_002900B8 the first keeps case 1/2's 128 multiply on r206 rather than its copy; the other
two give text call 2 retail's `mov.s $f14,$f22 ... mov.s $f15,$f14` argument copies.

Forced on for every USA v1.01 C unit they change 13, 9 and 0 functions (22 together): opt-in
per-unit models under the owner's standard of 12 November 2026. Default compilation is unchanged.

Usage: cse_arg_rules.py <gcc directory>
"""
import sys
from pathlib import Path

HUNKS = {'cse.c': [('\n#define PATHLENGTH\t10\n\n/* This data describes a block that will be processed by cse_basic_block.  */\n\nstruct cse_basic_block_data {\n', '\n#define PATHLENGTH\t10\n\n/* RAC2: nonzero while cse_main runs for the pass after loop.  */\nstatic int rac2_cse_after_loop;\n\n/* This data describes a block that will be processed by cse_basic_block.  */\n\nstruct cse_basic_block_data {\n'), ('\t\t  || ((uid_cuid[REGNO_LAST_UID (new)] > cse_basic_block_end\n\t\t       || (uid_cuid[REGNO_FIRST_UID (new)]\n\t\t\t   < cse_basic_block_start))\n\t\t      && (uid_cuid[REGNO_LAST_UID (new)]\n\t\t\t  > uid_cuid[REGNO_LAST_UID (firstr)]))))))\n    {\n', '\t\t  || ((uid_cuid[REGNO_LAST_UID (new)] > cse_basic_block_end\n\t\t       || (uid_cuid[REGNO_FIRST_UID (new)]\n\t\t\t   < cse_basic_block_start))\n\t\t      /* RAC2: -frac2-cse2-keep-multi-set-reg: after loop, a\n\t\t\t pseudo set once does not displace one with several\n\t\t\t sets.  */\n\t\t      && ! (flag_rac2_cse2_keep_multi_set_reg\n\t\t\t    && rac2_cse_after_loop\n\t\t\t    && REG_N_SETS (firstr) > 1\n\t\t\t    && REG_N_SETS (new) == 1)\n\t\t      && (uid_cuid[REGNO_LAST_UID (new)]\n\t\t\t  > uid_cuid[REGNO_LAST_UID (firstr)]))))))\n    {\n'), ("\t         && ! exp_equiv_p (elt->exp, elt->exp, 1, 0))\n\t    elt = elt->next_same_value;\t     \n\n\t  /* A paradoxical subreg would be bad here: it'll be the right\n\t     size, but later may be adjusted so that the upper bits aren't\n\t     what we want.  So reject it.  */\n", "\t         && ! exp_equiv_p (elt->exp, elt->exp, 1, 0))\n\t    elt = elt->next_same_value;\t     \n\n\t  /* RAC2: -frac2-cse-arg-hard-reg: a hard register whose source is a\n\t     constant or a hard register is not loaded from a pseudo that has\n\t     several sets.  For a constant, another hard register of that\n\t     pseudo's quantity is used when there is one.  */\n\t  if (flag_rac2_cse_arg_hard_reg\n\t      && elt && GET_CODE (elt->exp) == REG\n\t      && REGNO (elt->exp) >= FIRST_PSEUDO_REGISTER\n\t      && REG_N_SETS (REGNO (elt->exp)) > 1\n\t      && GET_CODE (dest) == REG && REGNO (dest) < FIRST_PSEUDO_REGISTER\n\t      && sets[i].src\n\t      && (CONSTANT_P (sets[i].src)\n\t\t  || (GET_CODE (sets[i].src) == REG\n\t\t      && REGNO (sets[i].src) < FIRST_PSEUDO_REGISTER)))\n\t    {\n\t      if (CONSTANT_P (sets[i].src) && GET_MODE (elt->exp) == mode)\n\t\t{\n\t\t  int r;\n\n\t\t  for (r = qty_first_reg[REG_QTY (REGNO (elt->exp))]; r >= 0;\n\t\t       r = reg_next_eqv[r])\n\t\t    if (r < FIRST_PSEUDO_REGISTER && r != REGNO (dest))\n\t\t      break;\n\t\t  if (r >= 0)\n\t\t    {\n\t\t      rtx hard = gen_rtx_REG (mode, r);\n\n\t\t      if (validate_change (insn, &SET_SRC (sets[i].rtl),\n\t\t\t\t\t   hard, 0))\n\t\t\t{\n\t\t\t  src = hard;\n\t\t\t  break;\n\t\t\t}\n\t\t    }\n\t\t}\n\t      elt = elt->next_same_value;\n\t      continue;\n\t    }\n\n\t  /* A paradoxical subreg would be bad here: it'll be the right\n\t     size, but later may be adjusted so that the upper bits aren't\n\t     what we want.  So reject it.  */\n"), ('  insn = f;\n  while (insn)\n    {\n      cse_end_of_basic_block (insn, &val, flag_cse_follow_jumps, after_loop,\n\t\t\t      flag_cse_skip_blocks);\n', '  insn = f;\n  while (insn)\n    {\n      rac2_cse_after_loop = after_loop;\n      cse_end_of_basic_block (insn, &val, flag_cse_follow_jumps, after_loop,\n\t\t\t      flag_cse_skip_blocks);\n')], 'reload1.c': [("\t{\n\t  /* Forget all the register values at a code label.  We don't\n             try to do anything clever around jumps.  */\n\t  for (i = 0; i < FIRST_PSEUDO_REGISTER; i++)\n\t    reg_values[i] = 0;\n", "\t{\n\t  /* Forget all the register values at a code label.  We don't\n             try to do anything clever around jumps.  */\n\n\t  /* RAC2: -frac2-reload-cse-branch-to-next: a label whose only users\n\t     are the conditional branches directly in front of it joins no\n\t     other path, so the values stay.  */\n\t  if (flag_rac2_reload_cse_branch_to_next)\n\t    {\n\t      rtx q;\n\t      int n = 0;\n\n\t      for (q = PREV_INSN (insn); q; q = PREV_INSN (q))\n\t\t{\n\t\t  if (GET_CODE (q) == NOTE)\n\t\t    continue;\n\t\t  if (GET_CODE (q) == JUMP_INSN && JUMP_LABEL (q) == insn\n\t\t      && condjump_p (q))\n\t\t    {\n\t\t      n++;\n\t\t      continue;\n\t\t    }\n\t\t  break;\n\t\t}\n\t      if (n > 0 && n == LABEL_NUSES (insn))\n\t\tcontinue;\n\t    }\n\n\t  for (i = 0; i < FIRST_PSEUDO_REGISTER; i++)\n\t    reg_values[i] = 0;\n")], 'toplev.c': [('/* RAC2: opt-in, no Cygnus block merging after the jump passes (GCC 2.95).  */\nint flag_rac2_keep_block_order = 0;\n\n//Dave - For devstudio integration\nint devstudioflag = 0;\n', "/* RAC2: opt-in, no Cygnus block merging after the jump passes (GCC 2.95).  */\nint flag_rac2_keep_block_order = 0;\n\n/* RAC2: opt-in, in the cse pass after loop a pseudo that is set once does\n   not replace, as a quantity's canonical register, a pseudo with several\n   sets.  */\nint flag_rac2_cse2_keep_multi_set_reg = 0;\n\n/* RAC2: opt-in, cse does not load a hard register from a pseudo that has\n   several sets when the insn's source is a constant or a hard register; for\n   a constant it uses another hard register that holds the value.  */\nint flag_rac2_cse_arg_hard_reg = 0;\n\n/* RAC2: opt-in, reload_cse keeps its register values at a label that is\n   reached only by the branches directly in front of it.  */\nint flag_rac2_reload_cse_branch_to_next = 0;\n\n//Dave - For devstudio integration\nint devstudioflag = 0;\n"), ('   "Perform a number of minor, expensive optimisations" },\n  {"rac2-keep-block-order", &flag_rac2_keep_block_order, 1,\n   "Do not merge blocks after the jump passes, as GCC 2.95"},\n  {"rac2-no-null-pointer-checks", &flag_rac2_no_null_pointer_checks, 1,\n   "Do not run the null-pointer-check pass, as GCC 2.95"},\n  {"rac2-narrow-saves-below", &flag_rac2_narrow_saves_below, 1,\n', '   "Perform a number of minor, expensive optimisations" },\n  {"rac2-keep-block-order", &flag_rac2_keep_block_order, 1,\n   "Do not merge blocks after the jump passes, as GCC 2.95"},\n  {"rac2-cse2-keep-multi-set-reg", &flag_rac2_cse2_keep_multi_set_reg, 1,\n   "After loop, cse keeps a several-set pseudo canonical over a set-once copy"},\n  {"rac2-cse-arg-hard-reg", &flag_rac2_cse_arg_hard_reg, 1,\n   "cse loads a hard register from a constant or hard register, not a several-set pseudo"},\n  {"rac2-reload-cse-branch-to-next", &flag_rac2_reload_cse_branch_to_next, 1,\n   "reload_cse keeps register values at a label reached only by adjacent branches"},\n  {"rac2-no-null-pointer-checks", &flag_rac2_no_null_pointer_checks, 1,\n   "Do not run the null-pointer-check pass, as GCC 2.95"},\n  {"rac2-narrow-saves-below", &flag_rac2_narrow_saves_below, 1,\n')], 'flags.h': [("\n/* RAC2: no Cygnus block merging after the jump passes.  */\nextern int flag_rac2_keep_block_order;\n\n/* Nonzero for -fwritable-strings:\n   store string constants in data segment and don't uniquize them.  */\n", "\n/* RAC2: no Cygnus block merging after the jump passes.  */\nextern int flag_rac2_keep_block_order;\nextern int flag_rac2_cse2_keep_multi_set_reg;\nextern int flag_rac2_cse_arg_hard_reg;\nextern int flag_rac2_reload_cse_branch_to_next;\n\n/* Nonzero for -fwritable-strings:\n   store string constants in data segment and don't uniquize them.  */\n")]}


def replace_once(text: str, before: str, after: str, label: str) -> str:
    if text.count(before) != 1:
        raise ValueError(f"{label}: expected one insertion point, found {text.count(before)}")
    return text.replace(before, after)


def patch(gcc: Path) -> None:
    paths = {name: gcc / name for name in HUNKS}
    sources = {name: path.read_text(encoding="latin-1") for name, path in paths.items()}
    if any("flag_rac2_cse_arg_hard_reg" in text for text in sources.values()):
        raise ValueError("cse arg rules already present")
    for name, hunks in HUNKS.items():
        for k, (old, new) in enumerate(hunks):
            sources[name] = replace_once(sources[name], old, new, f"{name} hunk {k}")
    for name, path in paths.items():
        path.write_text(sources[name], encoding="latin-1", newline="")


if __name__ == "__main__":
    patch(Path(sys.argv[1]))
